// ── SCE Accepted Subset 2.12: typed host-run invoke interface ──
/// `sce:result`: the record the host completes `<invoke id="clock">`
/// with (SCE Accepted Subset §2.12).
#[derive(Clone, Debug, Default, PartialEq)]
pub struct StaticInvokeTreeSceSynthInvokeWorkerClockResult {
    pub error: ::sce_rust_runtime::SceString,
    pub utc_ms: i64,
    pub monotonic_ms: i64,
}

impl StaticInvokeTreeSceSynthInvokeWorkerClockResult {
    /// The JSON `done.invoke.clock` carries this record as.
    pub fn wire(&self) -> ::sce_rust_runtime::SceString {
        ::sce_rust_runtime::payload_wire(format_args!(
            "{{\"error\":{}, \"utc_ms\":\"{}\", \"monotonic_ms\":\"{}\"}}",
            ::sce_rust_runtime::event_payload::quote(&self.error),
            self.utc_ms,
            self.monotonic_ms
        ))
    }
}

/// The host side of this document's typed `<invoke type="sce-host-clock-now">`s
/// (SCE Accepted Subset §2.12). Register it with
/// `register_sce_host_clock_now_invoker`.
pub trait StaticInvokeTreeSceSynthInvokeWorkerSceHostClockNowInvoker: Send + 'static {
    /// §scxml-6.4: begin `<invoke id="clock">`. `token` names this start;
    /// a host that finishes later hands it back to `complete_clock` (or
    /// `complete_host_invoke`). `Some` completes the invocation now.
    fn start_clock(
        &mut self,
        token: u64,
    ) -> Option<StaticInvokeTreeSceSynthInvokeWorkerClockResult>;
    /// §scxml-6.4: `<invoke id="clock">`'s state exited while the start
    /// `token` names was still running. Stop it.
    fn cancel_clock(&mut self, token: u64);
}

/// Registration and typed completion for this document's typed host-run
/// invokes. Bring into scope with `use …::StaticInvokeTreeSceSynthInvokeWorkerHostInvokers;`.
pub trait StaticInvokeTreeSceSynthInvokeWorkerHostInvokers {
    /// Complete `<invoke id="clock">`'s start `token` with its record —
    /// `complete_host_invoke` with the record's JSON, so a stale or unknown
    /// token is refused the same way (`false`).
    fn complete_clock(
        &mut self,
        token: u64,
        result: StaticInvokeTreeSceSynthInvokeWorkerClockResult,
    ) -> bool;
    /// Register `invoker` as the handler for `type="sce-host-clock-now"`.
    fn register_sce_host_clock_now_invoker<I>(&mut self, invoker: I)
    where
        I: StaticInvokeTreeSceSynthInvokeWorkerSceHostClockNowInvoker;
}

impl StaticInvokeTreeSceSynthInvokeWorkerHostInvokers
    for ::sce_rust_runtime::Engine<StaticInvokeTreeSceSynthInvokeWorkerPolicy>
{
    fn complete_clock(
        &mut self,
        token: u64,
        result: StaticInvokeTreeSceSynthInvokeWorkerClockResult,
    ) -> bool {
        self.complete_host_invoke("sce-host-clock-now", "clock", token, &result.wire())
    }
    fn register_sce_host_clock_now_invoker<I>(&mut self, mut invoker: I)
    where
        I: StaticInvokeTreeSceSynthInvokeWorkerSceHostClockNowInvoker,
    {
        self.register_invoker("sce-host-clock-now", move |event| match event {
            ::sce_rust_runtime::HostInvokeEvent::Start(request) => match request.invoke_id.as_str()
            {
                "clock" => invoker.start_clock(request.token).map(|result| {
                    ::sce_rust_runtime::HostInvokeResponse {
                        done_data: Some(StaticInvokeTreeSceSynthInvokeWorkerClockResult::wire(
                            &result,
                        )),
                        ..::sce_rust_runtime::HostInvokeResponse::default()
                    }
                }),
                _ => None,
            },
            ::sce_rust_runtime::HostInvokeEvent::Cancel(cancel) => {
                match cancel.invoke_id.as_str() {
                    "clock" => {
                        invoker.cancel_clock(cancel.token);
                        None
                    }
                    _ => None,
                }
            }
        });
    }
}

